-- LLM-783 down: remove the ten visitor outfit sprites. A visitor still on one
-- is cleared to no sprite first (actor.sprite_id has an FK); the engine's
-- rehydrate stamps his sprite again by name from the reverted code.

BEGIN;

UPDATE public.actor
   SET sprite_id = NULL
 WHERE sprite_id IN (
     '783f0c01-0000-4000-8000-000000000001', '783f0c01-0000-4000-8000-000000000002',
     '783f0c01-0000-4000-8000-000000000003', '783f0c01-0000-4000-8000-000000000004',
     '783f0c01-0000-4000-8000-000000000005', '783f0c01-0000-4000-8000-000000000006',
     '783f0c01-0000-4000-8000-000000000007', '783f0c01-0000-4000-8000-000000000008',
     '783f0c01-0000-4000-8000-000000000009', '783f0c01-0000-4000-8000-000000000010');

DELETE FROM public.npc_sprite
 WHERE id IN (
     '783f0c01-0000-4000-8000-000000000001', '783f0c01-0000-4000-8000-000000000002',
     '783f0c01-0000-4000-8000-000000000003', '783f0c01-0000-4000-8000-000000000004',
     '783f0c01-0000-4000-8000-000000000005', '783f0c01-0000-4000-8000-000000000006',
     '783f0c01-0000-4000-8000-000000000007', '783f0c01-0000-4000-8000-000000000008',
     '783f0c01-0000-4000-8000-000000000009', '783f0c01-0000-4000-8000-000000000010');

COMMIT;
